import { fileURLToPath } from "node:url";

import { migrate } from "drizzle-orm/postgres-js/migrator";

import { createDatabase } from "./client";

/** SQL migrations generated by drizzle-kit (plus hand-written ones), applied in journal order. */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL("../../drizzle", import.meta.url));

/**
 * Apply pending migrations on its own single connection. Drizzle records
 * applied migrations in `drizzle.__drizzle_migrations` and runs the pending
 * ones in one transaction.
 */
export async function runMigrations(url: string, migrationsFolder = MIGRATIONS_FOLDER): Promise<void> {
  const { db, close } = createDatabase({ url, max: 1 });
  try {
    await migrate(db, { migrationsFolder });
  } finally {
    await close();
  }
}
